/**
 * CZ-125 engineering QA for the exact founder-supplied original A–H.
 * Uses only invented *test input strings* in memory. NO real participant
 * evidence and NO efficacy/learning claims are generated by these tests.
 */
import {test} from "node:test";
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {Script} from "node:vm";
import {inspectResearchBundle,STUDY,summarizePrivateDirectory}
 from "./audit-local-evidence.mjs";

const load=name=>readFileSync(new URL(name,import.meta.url),"utf8");
const candidate="73849bff27fc73db97d5fb015c57f45323e18f30";
const source="cc99ce7c-4037-44a6-b199-760698937258";
const QA="QA-ONLY — synthetic validation input; NOT a human answer";

test("provenance pins founder-supplied full A–H transcription, not unreadable native document",()=>{
 for(const filename of ["PREREG-RECONCILIATION-v0.1.md",
  "PROTOCOL.md","FOUNDER-GATE.md","reader-response.html"])
  assert.ok(load(filename).includes(candidate),filename);
 for(const filename of ["PREREG-RECONCILIATION-v0.1.md","PROTOCOL.md",
  "FOUNDER-GATE.md","reader-response.html"])
  assert.ok(load(filename).includes(source),filename);
 assert.equal(STUDY.fullFounderTranscriptionRecovered,true);
 assert.equal(STUDY.nativeDocumentRead,false);
 assert.equal(STUDY.originalDocId,"bf106341-8403-4c88-a71a-67d414f2972d");
});
test("A–H corrects five paired participants, ten observations and original fixed sample orders",()=>{
 assert.equal(STUDY.participants,5);
 assert.equal(STUDY.observations,10);
 assert.equal(STUDY.perGameObservations,5);
 assert.deepEqual(STUDY.assignedOrder,{
  P01:["dillard","kierkegaard"],P02:["kierkegaard","dillard"],
  P03:["dillard","kierkegaard"],P04:["kierkegaard","dillard"],
  P05:["dillard","kierkegaard"]
 });
 const protocol=load("PROTOCOL.md");
 for(const id of ["P01","P02","P03","P04","P05"])
  assert.ok(protocol.includes(id));
 assert.match(protocol,/10 participant×game/i);
 assert.doesNotMatch(protocol,/10 unique people|required 10 distinct readers/i);
});
test("C and D recovered question wording EXACT, misconception options, transfer and engagement in offline HTML",()=>{
 const html=load("reader-response.html");
 const exact=[
  "What is the dilemma? Which parts could you decide yourself?",
  "In your own words, what is this experience asking you to do? What will it help you see?",
  "What is the philosopher's main point? How did your decisions or events illustrate it? Which parts were not within your control or not known?",
  "Five imagined evenings can illustrate a time-use pattern, but don't prove real-life priorities.",
  "More writing tokens prove writing is the better way to live.",
  "The game can tell exactly what you do on an average night.",
  "Later invented events show the unchosen job would have been worse.",
  "You chose your response, but not which real event happened; the unchosen path remains unknown.",
  "Looking backward lets you judge the first decision with complete certainty.",
  "A reader models a week with two hours of reading and five hours of rest each day. What can they conclude, and what can't they?",
  "A person moves city and discovers later that the apartment is noisier than advertised. Does this prove moving was foolish or that staying would have been better? Why?",
  "Which moment was clearest? What confused you? What if anything was worth remembering? Which interaction felt more meaningful and why?",
  "Describe one central idea from Dillard and one from Kierkegaard, and give a specific example from each game. Identify one thing the game could NOT tell you about reality."
 ];
 for(const sentence of exact)assert.ok(html.includes(sentence),"missing A-H original literal: "+sentence);
 for(const key of ["baseline","glance","immediate","delayed"])
  assert.ok(html.includes('"'+key+'"'));
 assert.doesNotMatch(html,/correct:\s*[AB]|correct answer|answerKey|correctOption|researcherOnlyKey/i);
 new Script(html.match(/<script>([\s\S]*?)<\/script>/i)[1],{filename:"cz125 A-H recorder"});
});
test("E six original dimensions and original F thresholds are not adjusted or silently pooled",()=>{
 assert.deepEqual(STUDY.dimensions,[
  "interaction_comprehension_0_2","philosophical_comprehension_baseline_post_0_4",
  "source_grounded_correctness_pass_review_block","counterexample_understanding_0_2",
  "delayed_recall_0_2","qualitative_engagement_verbatim"
 ]);
 assert.deepEqual(STUDY.thresholds,{
  interactionFullPerGame:4,interactionPossiblePerGame:5,
  philosophyPostAtLeast3PerGame:4,philosophyPossiblePerGame:5,
  nonRegressingImprovers:3,improverPossible:5,minImprovementOneGame:1,
  counterexampleFullPerGame:4,counterexamplePossiblePerGame:5,
  validFollowups:4,followupPossible:5,
  bothIdeasFullDelayed:3,delayedPossible:5,
  sourceReviewerBothRequired:true,noUnresolvedP0:true
 });
 assert.deepEqual(STUDY.followupHours,{min:20,max:28});
 assert.deepEqual(STUDY.originalCorrectOptionsResearcherOnly,{dillard:"A",kierkegaard:"B"});
 const p=load("PROTOCOL.md");
 for(const label of ["Interaction comprehension","Philosophical comprehension",
  "Source-grounded correctness","Counterexample understanding",
  "Delayed recall","Qualitative engagement"])assert.ok(p.includes(label));
 assert.match(p,/without regression/i);
 assert.match(p,/both ideas/i);
 assert.match(p,/missing = null/i);
});
test("privacy and method lock: no network/storage, separate consent, no unsanctioned exports or fake participants",()=>{
 const html=load("reader-response.html");
 for(const bad of [
  /<script[^>]+src=/i,/<link[^>]+href=["']https?:/i,
  /\b(?:fetch|XMLHttpRequest|sendBeacon)\s*\(/i,/\b(?:localStorage|sessionStorage|indexedDB)\b/i,
  /\b(?:track|analytics)\s*\(/i
 ])assert.doesNotMatch(html,bad);
 assert.match(html,/const METHOD_RELEASE_APPROVED=false/);
 assert.match(html,/id="recontact"/);
 assert.match(html,/id="consent"/);
 assert.match(html,/id="adult"/);
 assert.match(html,/type="file"/);
 assert.match(html,/new Blob\(/);
 assert.match(html,/!METHOD_RELEASE_APPROVED/);
 assert.equal(STUDY.enrollmentAuthorized,false);
 assert.equal(STUDY.methodReleaseApproved,false);
 const empty=summarizePrivateDirectory();
 assert.equal(empty.actualVerifiedHumanParticipants,0);
 assert.equal(empty.actualVerifiedHumanGameRows,0);
 assert.equal(empty.actualVerifiedPhilosophicalGains,0);
 assert.equal(empty.status,"METHOD_REVIEW_PENDING");
});
function qaBundle(progress=6){
 const start="2026-11-15T08:00:00.000Z";
 const games=STUDY.assignedOrder.P02;
 const rows=games.map((name,i)=>({
  participant_id:"P02",code_sha:candidate,
  sequence_order:i+1,condition:name==="dillard"?"token_studio":"swipe_decision",
  source_record_id:name==="dillard"?"research:dillard:time-v1":"research:kierkegaard:future-v1",
  consent:{anonymous_written:true,recontact:true},
  baseline_verbatim:QA,baseline_at:"2026-11-15T08:00:00.000Z",
  first_glance_verbatim:QA,first_glance_at:"2026-11-15T08:01:00.000Z",
  interaction_score_0_2:null,chosen_canonical_path:"QA TEST ONLY",
  post_verbatim:QA,misconception_choice:"A",
  misconception_reason_verbatim:QA,
  transfer_answer_verbatim:QA,qualitative_quote:QA,
  interaction_observation:QA,intervention_notes:"QA simulated interaction (not real)",
  immediate_at:"2026-11-15T08:02:00.000Z",
  comprehension_before_0_4:null,comprehension_after_0_4:null,
  counterexample_score_0_2:null,delayed_score_0_2:null,
  source_grounded_correctness:null,scorer_id:null,
  delayed_missing:true,delayed_date_time:null,delayed_answer_verbatim:null
 }));
 const b={
  testOnly:true,schema:STUDY.schema,protocolVersion:STUDY.protocolVersion,
  code_sha:candidate,sourceCommentId:source,participant_id:"P02",
  consent:{anonymous_written:true,recontact:true},automaticScoring:false,
  order:[...games],rows,progress,
  studyEndedAt:"2026-11-15T08:03:00.000Z",delayed:null
 };
 return b;
}
test("G structural validator accepts complete *explicitly QA-only* A–H flow but never counts it as a human",()=>{
 const b=qaBundle();
 const checked=inspectResearchBundle(b,{allowQaTestOnly:true});
 assert.equal(checked.valid,true,JSON.stringify(checked.errors));
 assert.equal(checked.reportedBaseline,2);
 assert.equal(checked.reportedFirstGlance,2);
 assert.equal(checked.reportedImmediate,2);
 assert.equal(checked.reportedDelayed,0);
 assert.equal(checked.humanIdentityVerified,false);
 assert.equal(checked.humanPhilosophicalScoresVerified,false);
 assert.equal(inspectResearchBundle(b).valid,false,"QA fixture is NEVER real evidence");
});
test("G structurally rejects tampering, missing baseline/immediate and improper human score bounds",()=>{
 const b=qaBundle();b.rows[0].condition="swipe_decision";
 assert.equal(inspectResearchBundle(b,{allowQaTestOnly:true}).valid,false);
 b.rows[0].condition="swipe_decision";
 b.rows[0].source_record_id="research:kierkegaard:future-v1";
 b.rows[0].misconception_choice="Z";
 assert.equal(inspectResearchBundle(b,{allowQaTestOnly:true}).valid,false);
 const missing=qaBundle();missing.rows[0].baseline_verbatim=null;
 assert.equal(inspectResearchBundle(missing,{allowQaTestOnly:true}).valid,false);
 const scores=qaBundle();scores.rows[0].comprehension_after_0_4=5;
 assert.equal(inspectResearchBundle(scores,{allowQaTestOnly:true}).valid,false);
});
test("D correct window, both ideas, missing-vs-observed zero validated without participant evidence",()=>{
 const b=qaBundle(7);
 const answer=QA;
 b.delayed={answer,at:"2026-11-16T08:03:00.000Z",
  hours:24,validWindow:true,validIndependent:true};
 b.rows.forEach(r=>{
  r.delayed_answer_verbatim=answer;r.delayed_date_time="2026-11-16T08:03:00.000Z";
  r.delayed_missing=false;r.delayed_score_0_2=0; // observed wrong vs missing
 });
 let x=inspectResearchBundle(b,{allowQaTestOnly:true});
 assert.equal(x.valid,true,JSON.stringify(x.errors));
 assert.equal(x.reportedDelayed,2);
 assert.equal(x.structurallyValidFollowup,true);
 b.delayed.at="2026-11-16T13:03:00.000Z";
 b.delayed.hours=29;b.delayed.validWindow=false;b.delayed.validIndependent=false;
 x=inspectResearchBundle(b,{allowQaTestOnly:true});
 assert.equal(x.valid,true,JSON.stringify(x.errors));
 assert.equal(x.structurallyValidFollowup,false);
 b.rows[0].delayed_missing=true;b.rows[0].delayed_score_0_2=0;
 assert.equal(inspectResearchBundle(b,{allowQaTestOnly:true}).valid,false);
});
test("review remains pending while source/device gates stay open and neutral wording is prospectively documented",()=>{
 const p=load("PROTOCOL.md"),rec=load("PREREG-RECONCILIATION-v0.1.md"),
  gate=load("FOUNDER-GATE.md"),preview=load("PRIVATE-HTTPS-PREVIEW.md");
 for(const q of ["N1","N2","N3","N4","N5"])assert.ok(rec.includes(q));
 assert.match(p,/prior to.*enrollment|before recruitment/i);
 assert.match(gate,/METHOD RELEASE PENDING/i);
 assert.match(gate,/0 \/ 5/);
 assert.match(gate,/0 \/ 10/);
 assert.match(preview,/NOT DEPLOYED/);
 assert.match(preview,/Host\/Origin/);
});
